+    fn extern_crate_root_declines_2015() {
+        let g = two_crate_graph();
+        let policy = RustPolicy::new(&g, 2015); // 2015: the bare fallback must not fire.
+        assert_eq!(
+            policy.extern_crate_root(&g, "b_crate", &Anchor::use_path_2015(), ScopeId(2)),
+            None
+        );
+    }
