+        let g = two_crate_graph();
+        assert_eq!(crate_root_of(&g, ScopeId(2)), Some(ScopeId(0)));
+        assert_eq!(crate_root_of(&g, ScopeId(0)), Some(ScopeId(0)));
+    }
+}
